SINA_SMART["anat2-vessels"] = {"lecture":"anat2-vessels","title":"Blood vessels of the abdomen","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat2-vessels:e0","text":"Abdominal aorta: T12 → bifurcation at L4.","topic":"The abdominal aorta","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-vessels:e1","text":"Coeliac trunk (T12): left gastric, common hepatic, splenic; foregut.","topic":"The abdominal aorta","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-vessels:e2","text":"SMA (L1): midgut; ileocolic, right and middle colic.","topic":"The abdominal aorta","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-vessels:e3","text":"IMA (L3): hindgut; left colic, sigmoid, superior rectal.","topic":"The abdominal aorta","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-vessels:e4","text":"Renal arteries L1-L2; gonadal arteries below them.","topic":"The abdominal aorta","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-vessels:e5","text":"Posterior: inferior phrenic, lumbar arteries.","topic":"The abdominal aorta","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-vessels:e6","text":"IVC: common iliacs at L5 → diaphragm at T8; right of aorta.","topic":"Inferior vena cava","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-vessels:e7","text":"IVC tributaries: none from gut or spleen; left gonadal → left renal vein.","topic":"Inferior vena cava","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-vessels:e8","text":"Portal vein: SMV + splenic (+ IMV) + gastric veins.","topic":"Portal vein and anastomoses","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-vessels:e9","text":"Portosystemic: oesophageal, paraumbilical, rectal, retroperitoneal; TIPS.","topic":"Portal vein and anastomoses","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"g8foax":"a","l7zfux":"a","gi3xwm":"a","xezc4y":"a","1f8r2xd":"a","1gocktp":"a","1yb30x6":"a","1se03wi":"a","94wp90":"a","1op2buc":"a","19ckaf0":"a","1bezp54":"a","vltf84":"a","1vn9p3d":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat2-vessels:e0":{"s":0,"u":["Abdominal aorta: T12 → bifurcation at L4.","The abdominal aorta continues the thoracic aorta at the diaphragm ( T12 ) and ends by bifurcating into the common iliac arteries at L4 ."],"dp":[{"h":"Note","t":"Abdominal aorta : enters at T12 , bifurcates at L4 (umbilicus level). Gut arteries: coeliac T12 (foregut) , SMA L1 (midgut) , IMA L3 (hindgut) . Renals ~L1-L2."}]},"anat2-vessels:e1":{"s":0,"u":["Coeliac trunk (T12): left gastric, common hepatic, splenic; foregut.","Coeliac trunk variants are common.","Anterior unpaired branches (digestive tract): coeliac trunk (T12) , foregut: left gastric (stomach, lower oesophagus), common hepatic (liver, gallbladder, pancreas, part of duodenum; gives the gastroduodenal artery), splenic (spleen, pancreas, stomach); superior mesenteric artery (L1) , midgut: small intestine except the duodenum, caecum, appendix, ascending colon and part of the transverse colon, via inferior pancreaticoduodenal, jejunal and ileal, ileocolic, right colic and middle colic arteries; inferior mesenteric artery (L3) , hindgut: descending and sigmoid colon, rectum, via left colic, sigmoid and superior rectal arteries."],"dp":[{"h":"Note","t":"Coeliac trunk = left gastric, common hepatic (→ GDA, proper hepatic, right gastric), splenic. SMA = inferior pancreaticoduodenal, jejunal/ileal, ileocolic, right and middle colic. IMA = left colic, sigmoid, superior rectal."}]},"anat2-vessels:e2":{"s":0,"u":["SMA (L1): midgut; ileocolic, right and middle colic.","Lateral branches : middle suprarenal, renal (just below the SMA, L1-L2: kidneys, adrenals, ureters).","Anterior unpaired branches (digestive tract): coeliac trunk (T12) , foregut: left gastric (stomach, lower oesophagus), common hepatic (liver, gallbladder, pancreas, part of duodenum; gives the gastroduodenal artery), splenic (spleen, pancreas, stomach); superior mesenteric artery (L1) , midgut: small intestine except the duodenum, caecum, appendix, ascending colon and part of the transverse colon, via inferior pancreaticoduodenal, jejunal and ileal, ileocolic, right colic and middle colic arteries; inferior mesenteric artery (L3) , hindgut: descending and sigmoid colon, rectum, via left colic, sigmoid and superior rectal arteries."],"dp":[]},"anat2-vessels:e3":{"s":0,"u":["IMA (L3): hindgut; left colic, sigmoid, superior rectal.","Anterior unpaired branches (digestive tract): coeliac trunk (T12) , foregut: left gastric (stomach, lower oesophagus), common hepatic (liver, gallbladder, pancreas, part of duodenum; gives the gastroduodenal artery), splenic (spleen, pancreas, stomach); superior mesenteric artery (L1) , midgut: small intestine except the duodenum, caecum, appendix, ascending colon and part of the transverse colon, via inferior pancreaticoduodenal, jejunal and ileal, ileocolic, right colic and middle colic arteries; inferior mesenteric artery (L3) , hindgut: descending and sigmoid colon, rectum, via left colic, sigmoid and superior rectal arteries."],"dp":[]},"anat2-vessels:e4":{"s":0,"u":["Renal arteries L1-L2; gonadal arteries below them.","Gonadal arteries (testicular or ovarian) arise below the renal arteries and run down on psoas (to the deep inguinal ring, or the suspensory ligament of the ovary).","Posterior branches : inferior phrenic and lumbar arteries (at risk in aortic surgery)."],"dp":[]},"anat2-vessels:e5":{"s":0,"u":["Posterior: inferior phrenic, lumbar arteries.","Posterior branches : inferior phrenic and lumbar arteries (at risk in aortic surgery).","Its branches are anterior, lateral and posterior, paired or unpaired."],"dp":[]},"anat2-vessels:e6":{"s":1,"u":["IVC: common iliacs at L5 → diaphragm at T8; right of aorta.","It forms by the union of the common iliac veins at L5 , ascends to the right of the aorta , and passes through the central tendon of the diaphragm at T8 .","Tributaries: common iliac, lumbar, gonadal (right into the IVC; left into the left renal vein), renal , right suprarenal, inferior phrenic and hepatic veins , but none from the digestive tract or spleen , which drain via the portal vein."],"dp":[{"h":"Note","t":"IVC : forms at L5 , right of the aorta, pierces the central tendon at T8 . It receives no gut or spleen blood (that goes via the portal vein)."}]},"anat2-vessels:e7":{"s":1,"u":["IVC tributaries: none from gut or spleen; left gonadal → left renal vein.","Tributaries: common iliac, lumbar, gonadal (right into the IVC; left into the left renal vein), renal , right suprarenal, inferior phrenic and hepatic veins , but none from the digestive tract or spleen , which drain via the portal vein.","Lumbar and azygos veins provide inferior-to-superior and left-to-right shunts."],"dp":[{"h":"Why a left varicocele can signal a kidney tumour","t":"The left testicular vein drains into the left renal vein at a right angle, while the right testicular vein enters the IVC directly. A left renal tumour extending into the renal vein can block that outflow, so the left pampiniform plexus swells into a varicocele. A new left varicocele in an adult, especially one that does not empty when lying down, prompts imaging of the left kidney. Source: the lecture's gonadal vessels and IVC tributaries."},{"h":"Note","t":"Left gonadal vein → left renal vein ; right gonadal → IVC directly. So a left renal tumour or vein obstruction can cause a left varicocele ."},{"h":"Clinical","t":"Nutcracker : the left renal vein runs between the SMA and aorta and can be compressed there."}]},"anat2-vessels:e8":{"s":2,"u":["Portal vein: SMV + splenic (+ IMV) + gastric veins.","Tributaries: superior mesenteric vein , splenic vein (receiving the inferior mesenteric vein), left and right gastric veins.","The portal vein collects blood from the digestive tract and spleen and carries it to the liver sinusoids, linking two capillary systems."],"dp":[]},"anat2-vessels:e9":{"s":2,"u":["Portosystemic: oesophageal, paraumbilical, rectal, retroperitoneal; TIPS.","Portosystemic anastomoses : oesophageal , paraumbilical , rectal and retroperitoneal .","In portal hypertension they dilate (oesophageal varices, caput medusae, rectal varices); treatments include TIPS (transjugular intrahepatic portosystemic shunt) and surgical shunts."],"dp":[{"h":"Note","t":"Portal vein = SMV + splenic vein (IMV usually joins the splenic). Portosystemic sites: oesophageal, paraumbilical, rectal, retroperitoneal. TIPS decompresses portal hypertension."}]}},"meta":{"g8foax":{"a":"recall","vg":"anat2-vessels:e0/recall/1"},"l7zfux":{"a":"recall","vg":"anat2-vessels:e1/recall/1"},"gi3xwm":{"a":"recall","vg":"anat2-vessels:e3/recall/1"},"xezc4y":{"a":"recall","vg":"anat2-vessels:e3/recall/1"},"1f8r2xd":{"a":"recall","vg":"anat2-vessels:e1/recall/2"},"1gocktp":{"a":"recall","vg":"anat2-vessels:e2/recall/1"},"1yb30x6":{"a":"recall","vg":"anat2-vessels:e4/recall/1"},"1se03wi":{"a":"recall","vg":"anat2-vessels:e4/recall/1"},"94wp90":{"a":"recall","vg":"anat2-vessels:e6/recall/1"},"1op2buc":{"a":"recall","vg":"anat2-vessels:e6/recall/2"},"19ckaf0":{"a":"recall","vg":"anat2-vessels:e7/recall/1"},"1bezp54":{"a":"recall","vg":"anat2-vessels:e7/recall/1"},"vltf84":{"a":"recall","vg":"anat2-vessels:e8/recall/1"},"1vn9p3d":{"a":"recall","vg":"anat2-vessels:e9/recall/1"}},"explRev":"a99a793a9c37"};
